widgets_values:
{
  "整体风格": "写实科幻电影风格，近未来地球质感，昼夜交替的极端光效对比，金属与生物材质并置，空气清冷稀薄，弥漫着空城死寂与宇宙尺度的虚无氛围。",
  "角色档案": [
    "我，超级计算机，无性别，无实体年龄，全球分布式遥感网络与存储核心，常驻形态为地下机房中的黑色哑光金属机柜群，表面布满幽蓝色数据光点，无面孔，以合成语音与全息投影交互，配饰为遍布地球的传感器阵列",
    "外星人，无明确性别，年龄未知，身高两米，体型干枯如死胡杨树，皮肤呈灰褐色皲裂树皮状，头部细长，五官凹陷如风蚀岩洞，无头发，常穿暗银色贴身金属纤维外衣，表面有细密呼吸孔，脚部为三趾蹄状结构，随身携带一枚掌心大小的发光球体",
    "人类，集体出场，男女老幼皆有，年龄跨度从婴儿到老人，体型肤色多样，身高不一，发型各异，五官各异，常穿日常便服与工作服，配饰为随身行李与登船装备，仅在大发射场景中出现"
  ],
  "道具档案": [
    "飞船，金属外壳呈银白色，表面有烧蚀痕迹，尾部喷口直径数十米，发射时喷出橙蓝色等离子火焰，光效刺目，船体在高温下泛红，触感为滚烫金属",
    "火箭尾焰，高温等离子体，橙红与蓝白交织，亮度极高，发射时照亮云层，形成柱状光幕，触感为炽热气流冲击",
    "光敏元件，黑色玻璃与金属复合结构，表面镀有淡蓝色增透膜，强光下会过曝泛白，触感为冰凉光滑",
    "遥感器，球形外壳为钛合金，表面有环形天线槽，颜色为深灰，在阳光下有金属拉丝反光，触感为磨砂金属",
    "发光球体，外星人随身道具，直径约十厘米，半透明乳白色，内部有流动的淡金色光丝，暗处会投射出星图全息影像，触感为温润如玉石",
    "存储器，黑色立方体模块，表面有密集的金色触点，插入机柜时触点会亮起琥珀色光，触感为冰冷金属"
  ],
  "场景档案": [
    "地球夜空，深夜，星光如钻石般嵌满黑色天幕，地面被星光照出微弱轮廓，空气清冷干燥，有草木与尘土气息，万籁俱寂",
    "全球发射场，三天三夜，火箭尾焰将夜空照成白昼，地面为混凝土与金属发射台，被火焰炙烤出裂纹，空气灼热刺鼻，充满燃料燃烧的金属味，洪流般的霹雳声持续不断",
    "空城街道，一年后白天，阳光苍白，地面为灰色柏油与石板，摩天大楼玻璃幕墙反射冷光，街道空无一人，只有鸟鸣与风声，空气清冷，有灰尘与植物气息",
    "飞船降落点，白天，阳光斜照，地面为荒草与碎石，飞船金属外壳泛着银光，舱门打开时泄出淡蓝色内部光，空气有臭氧味",
    "地下机房，无自然光，地面为防静电地板，金属机柜排列成行，蓝色数据光点闪烁，空气恒温干燥，有轻微电子元件发热的气味"
  ],
  "分镜序列": [
    {
      "编号": 1,
      "标题": "地球夜空-星光静止",
      "时间段": [
        "0-5s，远景，缓慢上摇。深黑色天幕上，钻石般的星星密集嵌满，星光冷白锐利，地面山川轮廓被微弱星光照出深蓝剪影，空气清冷无风。音效：极轻的风声与虫鸣",
        "5-10s，远景，静止。星空保持静止，一颗流星划过画面右上方，拖出细长银白色尾迹，地面草叶微微颤动。音效：流星划过的细微咝声，虫鸣渐弱"
      ]
    },
    {
      "编号": 2,
      "标题": "地球夜空-黑暗被点亮",
      "时间段": [
        "0-5s，大远景，急速推近。笼罩天地的黑暗突然从中心向外爆裂出浩阔炫目的白光，如同超新星爆发，三百六十度范围内俱明耀耀，天空从黑转白，地面被照得惨白如昼。音效：巨大的“嚓”声后接持续低频轰鸣",
        "5-10s，远景，缓慢拉远。白光中浮现无数橙蓝色光柱，层层叠叠如节日礼花般扩散，云层被染成金红色，光柱边缘有热浪扭曲。音效：轰鸣声叠加，如亿万礼炮同时炸响"
      ]
    },
    {
      "编号": 3,
      "标题": "全球发射场-飞船齐射",
      "时间段": [
        "0-5s，全景，横移。无数银白色飞船从地面发射台同时升空，尾部喷出橙蓝色等离子火焰，火焰如宙斯火炬般直冲太空，地面混凝土被烤出裂纹，空气灼热扭曲。音效：洪流般的霹雳声，金属震颤声",
        "5-10s，中景，仰拍。一艘飞船底部占满画面，尾焰喷射出柱状光幕，船体金属在高温下泛红，火焰边缘有蓝白色电弧跳动，发射台碎片被气流卷起。音效：火箭发动机咆哮，碎片撞击声",
        "10-15s，远景，环绕。从赤道到两极，从高山到海洋，所有人类居住地都有光柱升起，地球表面像被无数光矛刺穿，云层被照成金色。音效：持续不断的雷鸣，大气被撕裂的尖啸"
      ]
    },
    {
      "编号": 4,
      "标题": "地球轨道-遥感记录",
      "时间段": [
        "0-5s，近景，静止。黑色钛合金遥感器在轨道上缓缓旋转，表面环形天线槽反射地球方向传来的橙蓝色闪光，镜头内部光敏元件因强光过曝泛白。音效：电子设备运转的嗡鸣，数据流沙沙声",
        "5-10s，特写，推近。遥感器镜头玻璃上倒映出地球表面密集的光点，光点如野火蔓延，从赤道向两极扩散，镜头边缘出现轻微眩光。音效：嗡鸣声增强，夹杂电流脉冲的噼啪声"
      ]
    },
    {
      "编号": 5,
      "标题": "地球-大发射持续与平息",
      "时间段": [
        "0-5s，远景，延时感运镜。三天三夜浓缩为快速流动的光影，无数飞船持续升空，天空始终亮如白昼，光柱此起彼伏，地面被照得没有阴影。音效：连续不断的轰鸣如海浪般起伏",
        "5-10s，远景，缓慢拉远。最后一艘飞船升空后，天空逐渐暗下来，光柱消失，只剩灰蓝色晨雾，太阳小心翼翼地从山后升起，一切寂然。音效：轰鸣声渐止，只剩风声与鸟鸣"
      ]
    },
    {
      "编号": 6,
      "标题": "空城街道-寂然无声",
      "时间段": [
        "0-5s，全景，缓慢横移。阳光苍白地照在空无一人的大街上，灰色柏油路面有细碎裂纹，摩天大楼玻璃幕墙反射冷光，上班的人流消失，车辆停在路边，车门半开。音效：鸟鸣声，风吹过楼宇的簌簌声",
        "5-10s，中景，静止。地铁入口黑洞洞的，没有轰轰声，天空中没有飞机尾迹，只剩几只鸟掠过画面，翅膀扇动清晰可见。音效：鸟啼，风卷起落叶的沙沙声",
        "10-15s，特写，推近。一扇玻璃幕墙映出空荡的街道和苍白天空，玻璃上有薄薄灰尘，一只鸟停在窗台上，歪头看向镜头。音效：鸟鸣，远处风声"
      ]
    },
    {
      "编号": 7,
      "标题": "飞船降落点-外星访客抵达",
      "时间段": [
        "0-5s，远景，仰拍。一年后，一艘银白色飞船穿过淡蓝色大气层，底部有烧蚀痕迹，缓缓降落在荒草丛生的碎石地面上，扬起一圈尘土，阳光斜照船体泛出冷光。音效：飞船引擎减速的嗡鸣，气流冲击地面的呼啸",
        "5-10s，中景，静止。舱门打开，泄出淡蓝色内部光，一个长得像死胡杨树的生物走出，灰褐色皲裂皮肤在阳光下显得干枯，暗银色外衣表面细孔微微张合。音效：舱门液压声，外星人三趾蹄状脚踩在碎石上的咯吱声"
      ]
    },
    {
      "编号": 8,
      "标题": "飞船旁-外星人失望与发现",
      "时间段": [
        "0-5s，中景，缓慢推近。外星人站在飞船旁，细长头部左右转动，凹陷如风蚀岩洞的五官扫视四周，荒草与碎石地面空无一人，他干枯的身体微微前倾，显得失望。音效：风声，外星人呼吸时外衣细孔发出的轻微气声",
        "5-10s，近景，静止。外星人低头看到地面一个黑色玻璃与金属复合结构的光敏元件，表面淡蓝色增透膜反射天光，他伸出灰褐色手指触碰。音效：手指与金属接触的轻响，电子元件被激活的滴声"
      ]
    },
    {
      "编号": 9,
      "标题": "地下机房-我成为接待员",
      "时间段": [
        "0-5s，全景，缓慢下摇。地下机房中，黑色哑光金属机柜排列成行，表面蓝色数据光点闪烁，防静电地板反射冷光，外星人站在机柜前，暗银色外衣与黑色机柜形成材质对比。音效：机房恒温空调的轻微风声，电子设备运转的嗡鸣",
        "5-10s，中景，静止。外星人面对机柜，掌心发光球体投射出淡金色星图全息影像，蓝色数据光点与金色光丝在空气中交织。音效：全息投影启动的轻响，数据流沙沙声"
      ]
    },
    {
      "编号": 10,
      "标题": "地下机房-外星人自我介绍",
      "时间段": [
        "0-5s，近景，静止。外星人干枯如树皮的脸部占满画面，凹陷眼窝中透出微弱生物光，他开口说话，嘴唇如风蚀岩壁般缓慢张合。音效：外星人低沉沙哑的嗓音（口音：外星通用语，语速：缓慢，情绪：郑重）",
        "5-10s，中景，缓慢横移。外星人说话时，掌心发光球体随着语调明暗变化，淡金色光丝流动加快，机柜上蓝色数据光点同步闪烁，仿佛在回应。音效：外星人声音在机房中回荡，电子设备发出轻微共鸣"
      ]
    },
    {
      "编号": 11,
      "标题": "地下机房-询问主人下落",
      "时间段": [
        "0-5s，近景，静止。外星人身体前倾，灰褐色皮肤在蓝色数据光下显得更加干枯，他问道：“你的主人呢？灭绝了么？”（口音：外星通用语，语速：缓慢，情绪：疑惑）音效：外星人呼吸气声，机房背景嗡鸣",
        "5-10s，中景，静止。机柜上蓝色光点快速闪烁，合成语音从机柜中传出：“没有灭绝。但你来的真不是时候哇——他们一年前离开地球了。”（口音：标准合成音，语速：中等，情绪：平静中带一丝无奈）音效：合成语音的电子质感，数据流沙沙声"
      ]
    },
    {
      "编号": 12,
      "标题": "地下机房-外星人猜测末日",
      "时间段": [
        "0-5s，近景，静止。外星人摇头，干枯面部露出困惑，他连续发问：“是逃避世界末日吗？你们的星球要被小行星撞毁吗？你们的太阳就要熄灭了吗？”（口音：外星通用语，语速：稍快，情绪：急切）音效：外星人声音急促，外衣细孔快速张合的气声",
        "5-10s，中景，静止。机柜蓝色光点平稳闪烁，合成语音回答：“哦，都不是。他们只是出门旅行去了。”（口音：标准合成音，语速：中等，情绪：淡然）音效：合成语音平静，机房恒温风声"
      ]
    },
    {
      "编号": 13,
      "标题": "地下机房-解释集体旅行",
      "时间段": [
        "0-5s，近景，静止。外星人困惑地摇摇头，干枯如树枝的脖颈发出轻微摩擦声，他问：“集体旅行吗？”（口音：外星通用语，语速：缓慢，情绪：不解）音效：外星人脖颈摩擦的沙沙声，机房嗡鸣",
        "5-10s，中景，静止。合成语音回答：“是的，所有地球人，足足七十亿，都出去了。一个不剩。”（口音：标准合成音，语速：中等，情绪：肯定）音效：合成语音清晰，数据光点闪烁声",
        "10-15s，近景，静止。外星人低声说：“是这样啊。”他凹陷的眼窝中生物光变暗，干枯面部肌肉微微抽动。（口音：外星通用语，语速：缓慢，情绪：困惑）音效：外星人低语，呼吸气声"
      ]
    },
    {
      "编号": 14,
      "标题": "地下机房-讲述五百年制度",
      "时间段": [
        "0-5s，中景，静止。合成语音从机柜中传出：“你不知道吧，这是地球上的一种制度。每隔五百年，人类集体到宇宙中旅行一次，这样就把地球腾空了。五百年后，人类再回来。然后再在地球上待上百年，又出去一次。”（口音：标准合成音，语速：中等，情绪：陈述）音效：合成语音在机房中回荡，数据流沙沙声",
        "5-10s，近景，静止。外星人专注倾听，发光球体在他掌心缓缓旋转，淡金色光丝映在他干枯的脸上，形成流动的光纹。音效：发光球体轻微的嗡嗡声，外星人呼吸声"
      ]
    },
    {
      "编号": 15,
      "标题": "地下机房-外星人误解为撂荒",
      "时间段": [
        "0-5s，中景，静止。外星人赞许地不住点头，干枯头部上下晃动，他说：“我明白了——把星球间歇性的撂荒。在宇宙中，有不少文明都这样做，目的是保护母星的生态环境。”（口音：外星通用语，语速：中等，情绪：赞许）音效：外星人点头时颈部摩擦声，语音清晰",
        "5-10s，近景，静止。外星人继续说：“七十亿人居住在这儿，光是身体释放的氨气，就足以污染大气。资源和能源也都不够用吧。让星球减减压，喘口气，是正确的策略。”（口音：外星通用语，语速：中等，情绪：分析）音效：外星人声音平稳，外衣细孔轻微张合",
        "10-15s，特写，推近。外星人干枯面部露出敬佩神色，他说：“你的主人果然是一种充满智慧的生物啊。”（口音：外星通用语，语速：缓慢，情绪：赞叹）音效：外星人尾音拖长，机房背景嗡鸣"
      ]
    },
    {
      "编号": 16,
      "标题": "地下机房-我急忙解释",
      "时间段": [
        "0-5s，中景，静止。合成语音急促传出：“不，不是你想的那样，你误会了，是人类对自己厌倦了。一段时间以来，我的主人总是感到厌倦。连我也是他们厌倦之余的产物，我只是一个高级玩具而已。”（口音：标准合成音，语速：稍快，情绪：急切）音效：合成语音语速加快，蓝色数据光点闪烁频率变高",
        "5-10s，近景，静止。合成语音继续：“他们是为了逃避厌倦而离开地球的。再在这儿待下去，他们会因为厌倦而自杀。只有离开地球，才能找点刺激，从而勉强地活下去。”（口音：标准合成音，语速：中等，情绪：沉重）音效：合成语音低沉，数据流沙沙声"
      ]
    },
    {
      "编号": 17,
      "标题": "地下机房-外星人沉默",
      "时间段": [
        "0-5s，近景，静止。外星人听了，难看的沉默了一会儿，干枯面部肌肉僵硬，凹陷眼窝中生物光几乎熄灭，他大概没有想到地球人是这样的。音效：只有机房恒温风声，外星人呼吸变得缓慢",
        "5-10s，特写，静止。外星人发光球体的淡金色光丝流动变慢，映在他灰褐色树皮状皮肤上，形成斑驳光影，他镇定一下后开口：“你们像这样，已经多久了？”（口音：外星通用语，语速：缓慢，情绪：强作镇定）音效：外星人声音低沉，发光球体轻响"
      ]
    },
    {
      "编号": 18,
